package org.gepnic.doors.masterapi.inbound;
import org.junit.jupiter.api.*;import org.gepnic.doors.inbound.*;import org.gepnic.doors.masterapi.entity.ApiClient;import org.gepnic.doors.masterapi.repository.ApiClientRepository;
import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.http.ResponseEntity;
import java.security.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
class WriteAesTest {
 static KeyPair pair(){try{var g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);return g.generateKeyPair();}catch(Exception e){throw new RuntimeException(e);}}
 static void configureKeys(WriteIntegrationService service){var key=pair();var provider=mock(WriteEncryptionKeys.class);try{when(provider.active()).thenReturn(Map.of("kid","test-key","publicKey",WriteCrypto.pem(key.getPublic()),"encryption",WriteCrypto.MODE));}catch(Exception e){throw new RuntimeException(e);}ReflectionTestUtils.setField(service,"encryptionKeys",provider);}
 @Test void encryptionAuthenticatesCiphertextAndSupportsLargeBodiesAndOrderIndependentFields()throws Exception{
  var keys=pair();byte[] plain=new byte[1048576];new SecureRandom().nextBytes(plain);String a=WriteCrypto.seal(plain,keys.getPublic(),"key-a"),b=WriteCrypto.seal(plain,keys.getPublic(),"key-a");assertThat(a).isNotEqualTo(b);assertThat(WriteCrypto.open(a,keys.getPrivate())).isEqualTo(plain);
  var parsed=WriteCrypto.envelope(a);var reordered=new LinkedHashMap<String,String>();for(var key:List.of("secureData","iv","encryptedKey","kid"))reordered.put(key,parsed.get(key));assertThat(WriteCrypto.open(InboundProtocol.JSON.writeValueAsString(reordered),keys.getPrivate())).isEqualTo(plain);
  var changed=new LinkedHashMap<>(parsed);var cipher=Base64.getDecoder().decode(changed.get("secureData"));cipher[0]^=1;changed.put("secureData",Base64.getEncoder().encodeToString(cipher));assertThatThrownBy(()->WriteCrypto.open(InboundProtocol.JSON.writeValueAsString(changed),keys.getPrivate())).isInstanceOf(GeneralSecurityException.class);
  assertThatThrownBy(()->WriteCrypto.open(a,pair().getPrivate())).isInstanceOf(GeneralSecurityException.class);
  assertThatThrownBy(()->WriteCrypto.envelope("{\"kid\":\"a\",\"kid\":\"b\",\"iv\":\"AA==\",\"secureData\":\"AA==\"}")).isInstanceOf(GeneralSecurityException.class);
 }
 @Test void controllerDecryptsBeforeBusinessLogicAndEncryptsResponseWithoutChangingRetryIdentity()throws Exception{
  var server=pair();var sender=pair();var client=new ApiClient();client.setClientId(30L);client.setIsActive(true);client.setClientPublicKey(WriteCrypto.pem(sender.getPublic()));var clients=mock(ApiClientRepository.class);when(clients.findByApiKey("test-api-key")).thenReturn(Optional.of(client));var service=mock(InboundGatewayService.class);var props=new InboundProperties();props.setEnabled(true);var keys=mock(WriteEncryptionKeys.class);when(keys.privateKey("key-a")).thenReturn(server.getPrivate());var controller=new InboundGatewayController(service,clients,props);ReflectionTestUtils.setField(controller,"encryptionKeys",keys);
  String id=UUID.randomUUID().toString(),plain="{\"agreement_no\":\"ABC\",\"amount\":1}";long ts=java.time.Instant.now().getEpochSecond();var submissions=new ArrayList<InboundProtocol.Submission>();
  doAnswer(i->{var sub=(InboundProtocol.Submission)i.getArgument(1);submissions.add(sub);return ResponseEntity.status(201).body(Map.of("outcome","STORED","requestId",id,"instanceId","UAT","recordVersion",1));}).when(service).executeEncrypted(eq(client),any(),any());
  for(int n=0;n<2;n++){
   String envelope=WriteCrypto.seal(plain.getBytes(StandardCharsets.UTF_8),server.getPublic(),"key-a");var request=request(envelope,id,ts);request.addHeader("X-DOORS-Signature",WriteCrypto.sign(WriteCrypto.requestText("agreement-data","UAT",id,1,-1,ts,6,envelope),sender.getPrivate()));var result=controller.write("agreement-data",request);assertThat(result.getStatusCode().value()).isEqualTo(201);String encrypted=result.getBody().toString();WriteCrypto.verify(WriteCrypto.responseText(id,201,encrypted),result.getHeaders().getFirst("X-DOORS-Response-Signature"),server.getPublic());assertThat(new String(WriteCrypto.open(encrypted,sender.getPrivate()),StandardCharsets.UTF_8)).contains("STORED");
  }
  assertThat(submissions).hasSize(2);assertThat(submissions.getFirst().payload()).isEqualTo(plain);assertThat(InboundProtocol.fingerprint(submissions.get(0))).isEqualTo(InboundProtocol.fingerprint(submissions.get(1)));
  String envelope=WriteCrypto.seal(plain.getBytes(),server.getPublic(),"key-a");var bad=request(envelope,id,ts);bad.addHeader("X-DOORS-Signature",WriteCrypto.sign(WriteCrypto.requestText("agreement-data","UAT",id,1,-1,ts,7,envelope),sender.getPrivate()));assertThat(controller.write("agreement-data",bad).getStatusCode().value()).isEqualTo(400);assertThat(submissions).hasSize(2);
  var stale=request(envelope,id,ts-1000);stale.addHeader("X-DOORS-Signature","AA==");assertThat(controller.write("agreement-data",stale).getStatusCode().value()).isEqualTo(400);
  var legacy=request(plain,id,ts);legacy.removeHeader("X-DOORS-Encryption");legacy.addHeader("X-DOORS-Signature","legacy-signature");doReturn(ResponseEntity.ok(Map.of("legacy",true))).when(service).execute(eq(client),any(),eq("legacy-signature"),any());assertThat(controller.write("agreement-data",legacy).getStatusCode().value()).isEqualTo(200);verify(service).execute(eq(client),any(),eq("legacy-signature"),any());
 }
 static MockHttpServletRequest request(String body,String id,long ts){var r=new MockHttpServletRequest();r.setContent(body.getBytes(StandardCharsets.UTF_8));r.addHeader("X-API-KEY","test-api-key");r.addHeader("X-DOORS-Encryption",WriteCrypto.MODE);r.addHeader("X-DOORS-Instance-ID","UAT");r.addHeader("Idempotency-Key",id);r.addHeader("X-DOORS-Schema-Version","1");r.addHeader("X-DOORS-Expected-Version","-1");r.addHeader("X-DOORS-Timestamp",String.valueOf(ts));r.addHeader("X-DOORS-Protocol-Version","1");r.addHeader("X-DOORS-Contract-Version","6");return r;}
 @Test void sdkCryptoIsIdenticalToServerImplementation()throws Exception{String source=Files.readString(Path.of("src/main/java/org/gepnic/doors/masterapi/inbound/WriteCrypto.java")).replace("\r\n","\n").replace("package org.gepnic.doors.masterapi.inbound;\n","").replace("public final class WriteCrypto","final class WriteCrypto");assertThat(Files.readString(Path.of("src/main/resources/inbound/sdk/WriteCrypto.java.txt")).replace("\r\n","\n")).isEqualTo(source);}
}
